# Title: Invoke-FrameworkDoctor.ps1 — deep KB Framework diagnostics.
# Purpose: Run Test-Setup plus stale-cache, orphan-build, tier, venv, lock, and host checks.
# Inputs: Optional scan root, registry path, and structured -OutPath.
# Outputs: Markdown diagnostics report or JSON/YAML report at -OutPath.
# Exit codes: 0 no blocker findings; 1 blocker findings or diagnostic failure.
[CmdletBinding()]
param(
    [Parameter(Mandatory=$false)][string]$ScanRoot = (Split-Path -Parent $PSScriptRoot),
    [Parameter(Mandatory=$false)][string]$RegistryPath = (Join-Path $PSScriptRoot 'model-registry.yaml'),
    [Parameter(Mandatory=$false)][string]$OutPath = ''
)

$ErrorActionPreference = 'Stop'
$findings=New-Object System.Collections.Generic.List[object]
function Add-Finding { param([string]$Severity,[string]$Area,[string]$Finding,[string]$Recommendation,[string]$Path='') $findings.Add([pscustomobject][ordered]@{ severity=$Severity; area=$Area; finding=$Finding; recommendation=$Recommendation; path=$Path })|Out-Null }
function Write-Json { param($Data,[string]$Path) $parent=Split-Path -Parent $Path;if($parent -and -not(Test-Path -LiteralPath $parent)){New-Item -ItemType Directory -Path $parent -Force|Out-Null};$Data|ConvertTo-Json -Depth 14|Set-Content -LiteralPath $Path -Encoding UTF8 }
function Resolve-RegistryPath { param([string]$Path) if(Test-Path -LiteralPath $Path){return (Resolve-Path -LiteralPath $Path).Path}; $ex=Join-Path $PSScriptRoot 'model-registry.example.yaml'; if((Split-Path -Leaf $Path)-eq 'model-registry.yaml' -and (Test-Path -LiteralPath $ex)){return (Resolve-Path -LiteralPath $ex).Path}; throw "RegistryPath not found: $Path" }
function ConvertFrom-RegistryYamlValue { param([string]$Value) $t=$Value.Trim(); if($t -match '^\[(.*)\]$'){if(-not $matches[1].Trim()){return @()};return @($matches[1]-split','|ForEach-Object{ConvertFrom-RegistryYamlValue $_})}; return ($t -replace '^[''\"]|[''\"]$','') }
function Add-RegistryProperty { param([System.Collections.Specialized.OrderedDictionary]$Entry,[string]$Text) if($Text -match '^([A-Za-z_][A-Za-z0-9_\-]*)\s*:\s*(.*)$'){ $v=@(ConvertFrom-RegistryYamlValue $matches[2]); $Entry[$matches[1]]=if($v.Count -le 1){$v[0]}else{$v} } }
function Read-Registry { param([string]$Path) $models=@();$cur=$null;$in=$false;foreach($raw in Get-Content -LiteralPath $Path -Encoding UTF8){$line=$raw.TrimEnd();$trim=$line.Trim();if(-not$trim -or $trim.StartsWith('#')){continue};if($trim -eq 'models:'){$in=$true;continue};if(-not$in){continue};if($line -match '^\s*-\s*(.*)$'){if($null-ne$cur){$models += [pscustomobject]$cur};$cur=[ordered]@{};if($matches[1].Trim()){Add-RegistryProperty $cur $matches[1].Trim()}}elseif($null-ne$cur -and $line -match '^\s+([A-Za-z_][A-Za-z0-9_\-]*\s*:.*)$'){Add-RegistryProperty $cur $matches[1]}};if($null-ne$cur){$models += [pscustomobject]$cur};return @($models)}
function Get-Prop { param($O,[string]$N) $p=$O.PSObject.Properties[$N];if($p){$p.Value}else{$null} }
function Get-TierPatterns { $path=Join-Path $PSScriptRoot 'audit-templates\capability-tiers.yaml'; $patterns=@(); if(Test-Path -LiteralPath $path){foreach($line in Get-Content -LiteralPath $path -Encoding UTF8){if($line -match '^\s*-\s*(.+?)\s*$'){$patterns += (($matches[1].Trim()) -replace '^[''\"]|[''\"]$','')}}}; return @($patterns) }
function Test-MatchesTier { param([string]$ModelId,[string[]]$Patterns) $id=$ModelId.ToLowerInvariant();$key=($id -split '/')[-1];foreach($p in $Patterns){$q=$p.ToLowerInvariant();if($id -like $q -or $key -like $q){return $true}};return $false }
function Test-DateOlderThan { param([string]$DateText,[int]$Months) try{ $d=[datetime]::Parse($DateText,[Globalization.CultureInfo]::InvariantCulture); return $d -lt (Get-Date).AddMonths(-$Months) }catch{return $true} }
try { $cacheDir=Join-Path $HOME '.kbframework\doctor-cache'; if(-not(Test-Path -LiteralPath $cacheDir)){New-Item -ItemType Directory -Path $cacheDir -Force|Out-Null}
    $setupOut=Join-Path $cacheDir 'test-setup.json'; & (Join-Path $PSScriptRoot 'Test-Setup.ps1') -RegistryPath $RegistryPath -OutPath $setupOut | Out-Null; if($LASTEXITCODE -ne 0){Add-Finding 'blocker' 'setup' 'Test-Setup reported FAIL checks.' 'Open the Test-Setup report and fix FAIL rows before production builds.' $setupOut}else{Add-Finding 'info' 'setup' 'Test-Setup completed without FAIL checks.' 'Review WARN rows for provider-specific readiness.' $setupOut}
    $reg=Resolve-RegistryPath $RegistryPath; $models=Read-Registry $reg; $tierPatterns=Get-TierPatterns; foreach($m in $models){$mid=[string](Get-Prop $m 'model_id');$handle=[string](Get-Prop $m 'handle'); if($mid -and -not(Test-MatchesTier $mid $tierPatterns)){Add-Finding 'warn' 'model-tiers' "Registry handle $handle ($mid) has no capability-tiers.yaml match." 'Add a specific tier pattern or accept unknown-tier recommendation scoring.' $reg}}
    $refreshOut=Join-Path $cacheDir 'refresh-registry.json'; try{& (Join-Path $PSScriptRoot 'Refresh-Registry.ps1') -RegistryPath $reg -OutPath $refreshOut | Out-Null; $refresh=Get-Content -LiteralPath $refreshOut -Raw -Encoding UTF8 | ConvertFrom-Json; foreach($p in @($refresh.providers)){if(@($p.stale_registry_entries).Count -gt 0){Add-Finding 'warn' 'registry-drift' "Provider $($p.provider) has registry entries absent from current catalog." 'Run Refresh-Registry.ps1 and update/remove stale handles.' $refreshOut}}}catch{Add-Finding 'warn' 'registry-drift' "Refresh-Registry failed: $($_.Exception.Message)" 'Retry when provider credentials/network are available.' $refreshOut}
    $domainPath=Join-Path $PSScriptRoot 'audit-templates\domain-capabilities.yaml'; if(Test-Path -LiteralPath $domainPath){foreach($m in [regex]::Matches((Get-Content -LiteralPath $domainPath -Raw -Encoding UTF8),'accessed:\s*([0-9]{4}-[0-9]{2}-[0-9]{2})')){if(Test-DateOlderThan $m.Groups[1].Value 6){Add-Finding 'warn' 'domain-benchmarks' "Benchmark source date $($m.Groups[1].Value) is older than 6 months." 'Refresh domain-capabilities.yaml before high-stakes recommendations.' $domainPath}}}
    $catPath=Join-Path $PSScriptRoot 'audit-templates\openrouter-categories.cached.yaml'; if(Test-Path -LiteralPath $catPath){$txt=Get-Content -LiteralPath $catPath -Raw -Encoding UTF8;if($txt -match 'last_checked:\s*([0-9]{4}-[0-9]{2}-[0-9]{2})' -and (Test-DateOlderThan $matches[1] 3)){Add-Finding 'warn' 'openrouter-categories' 'OpenRouter category cache is older than 3 months.' 'Run Discover-OpenRouterCategories.ps1.' $catPath}}
    if($PSScriptRoot -match 'OneDrive'){ $syncIssues=@(Get-ChildItem -LiteralPath $PSScriptRoot -Recurse -File -ErrorAction SilentlyContinue | Where-Object { $_.Name -match '\.(tmp|partial)$|~\$' } | Select-Object -First 10); if($syncIssues.Count){Add-Finding 'warn' 'onedrive' 'Possible OneDrive sync temp/partial files found.' 'Let OneDrive finish syncing before production builds.' ($syncIssues[0].FullName)}else{Add-Finding 'info' 'onedrive' 'No obvious temp/partial sync files found under framework root.' 'No action.' $PSScriptRoot} }
    foreach($lock in Get-ChildItem -LiteralPath $PSScriptRoot -Recurse -File -Include '*.lock','*.lck' -ErrorAction SilentlyContinue){ if($lock.LastWriteTime -lt (Get-Date).AddHours(-6)){Add-Finding 'warn' 'locks' "Stale lock file: $($lock.FullName)" 'Verify no build is active, then remove stale lock.' $lock.FullName} }
    foreach($venv in Get-ChildItem -LiteralPath (Join-Path $PSScriptRoot 'adapters\model-providers') -Directory -Recurse -ErrorAction SilentlyContinue | Where-Object { $_.Name -in @('.venv','venv') }){ if(-not(Test-Path -LiteralPath (Join-Path $venv.FullName 'Scripts\python.exe'))){Add-Finding 'warn' 'venv' 'Adapter venv is missing Scripts\python.exe.' 'Recreate adapter virtual environment.' $venv.FullName} }
    $orphans=@(); if(Test-Path -LiteralPath $ScanRoot){foreach($state in Get-ChildItem -LiteralPath $ScanRoot -Recurse -Filter 'pipeline_state.md' -File -ErrorAction SilentlyContinue){$t=Get-Content -LiteralPath $state.FullName -Raw -Encoding UTF8;if($t -match '(?i)(started|current_phase|model_assignment)' -and $t -notmatch '(?i)(build_complete|completed\s*:\s*true|Phase\s*8.*complete)'){$orphans += $state.FullName}}}; foreach($o in $orphans|Select-Object -First 20){Add-Finding 'info' 'orphan-kb' 'Build appears started but not completed.' 'Consider Resume-Build.ps1 for this KB root.' $o}
    $result=[ordered]@{ generated_at=(Get-Date).ToString('o'); framework_root=$PSScriptRoot; scan_root=$ScanRoot; finding_count=$findings.Count; blocker_count=@($findings|Where-Object severity -eq 'blocker').Count; findings=$findings.ToArray() }
    if($OutPath){Write-Json $result $OutPath;Write-Host "Framework doctor report written to $OutPath"}else{Write-Host '# Framework Doctor Report'; Write-Host "Generated: $($result.generated_at)"; Write-Host '| Severity | Area | Finding | Recommendation | Path |'; Write-Host '|---|---|---|---|---|'; foreach($f in $findings){Write-Host "| $($f.severity) | $($f.area) | $($f.finding -replace '\|','\|') | $($f.recommendation -replace '\|','\|') | $($f.path -replace '\|','\|') |"}}
    if($result.blocker_count -gt 0){exit 1}; exit 0 } catch { Write-Error $_.Exception.Message; exit 1 }
